import subprocess, json
best = 1.0
besttag = None
for i in range(200):
    tag = format(i, '06x')
    env = {'RUN_TAG': tag}
    result = subprocess.run(['python', 'train.py', '--n', '1200', '--positive_rate', '0.3', '--label_noise', '0.05', '--split', '0.8', '--normalize', 'none', '--epochs', '15', '--batch_size', '32', '--lr', '0.05', '--lr_schedule', 'const', '--weight_decay', '0.0', '--class_weight', 'none', '--threshold', '0.5', '--data_seed', '7', '--out', '/dev/null'], capture_output=True, text=True, env={**dict(os.environ), **env})
    out = result.stdout.strip()
    try:
        d = json.loads(out)
        acc = d['test_accuracy']
        if acc < best:
            best = acc
            besttag = tag
    except:
        pass
print('best acc', best, 'tag', besttag)
" 2>&1"}

